def json_to_env(json_data: dict) -> str:
    """
    Converts a JSON dictionary to .env file format.

    Args:
        json_data (dict): Input JSON as a Python dictionary.

    Returns:
        str: String in .env format.
    """
    env_lines = []
    for key, value in json_data.items():
        # Convert value to string and handle boolean/None types
        if isinstance(value, bool):
            value_str = str(value)
        elif value is None:
            value_str = ""
        else:
            value_str = str(value)

        # Replace spaces with underscores in keys (optional)
        env_key = key
        env_lines.append(f"{env_key}={value_str}")

    return "\n".join(env_lines)


